import { cellWidth } from './markdown'
import { render } from './vendor/lovely-mermaid.js'

// mermaid 를 박스 문자 그림으로 그린다(lovely-mermaid). 렌더러가 칸마다 역할(border·text·edge·edgeLabel)을
// 붙여 주므로, 테두리는 흐리게·글자는 본문색·화살표만 강조색으로 칠한다. 한글 폭도 렌더러가 맞춘다.

export type Segment = { text: string; kind: 'border' | 'text' | 'line' | 'arrow' | 'label'; href?: string }

export type Diagram = { rows: Segment[][]; width: number }

type Cell = { ch: string; kind: Segment['kind']; href?: string; isContinuation?: boolean }

// 일반 노드 상자는 둥근 모서리로. 분기 노드의 이중선(╔╗╚╝)은 구분되도록 그대로 둔다.
const ROUNDED: Record<string, string> = { '┌': '╭', '┐': '╮', '└': '╰', '┘': '╯' }

// 글꼴의 ▼ 는 칸 안에 여백을 두고 작게 그려져 선·상자와 떨어져 보인다. 화살표 칸은 선으로 잇고,
// 그 앞 상자 테두리 칸에 Ghostty 가 칸 가장자리까지 그리는 삼각형 블록을 꽂는다.
const HEADS: Record<string, { dy: number; dx: number; line: string; block: string }> = {
  '▼': { dy: 1, dx: 0, line: '│', block: '\u{1FB6D}' },
  '▲': { dy: -1, dx: 0, line: '│', block: '\u{1FB6F}' },
  '▶': { dy: 0, dx: 1, line: '─', block: '\u{1FB6C}' },
  '►': { dy: 0, dx: 1, line: '─', block: '\u{1FB6C}' },
  '◀': { dy: 0, dx: -1, line: '─', block: '\u{1FB6E}' },
  '◄': { dy: 0, dx: -1, line: '─', block: '\u{1FB6E}' },
}

const cache = new Map<string, Diagram | null>()

function toCells(row: ReadonlyArray<{ text: string; role: string; href?: string }>): Cell[] {
  const cells: Cell[] = []
  for (const span of row) {
    const kind: Cell['kind'] =
      span.role === 'border' ? 'border' : span.role === 'edge' ? 'line' : span.role === 'edgeLabel' ? 'label' : 'text'
    for (const ch of span.text) {
      const cell: Cell = { ch, kind, ...(span.href ? { href: span.href } : {}) }
      if (kind === 'border') cell.ch = ROUNDED[ch] ?? ch
      if (kind === 'line' && HEADS[ch]) cell.kind = 'arrow'
      cells.push(cell)
      // 두 칸 글자 뒤에 자리만 차지하는 칸을 둬서 칸 좌표로 위아래 이웃을 찾을 수 있게 한다
      if (cellWidth(ch) === 2) cells.push({ ch: '', kind, isContinuation: true })
    }
  }
  return cells
}

export function plugArrows(grid: Cell[][]): void {
  for (let y = 0; y < grid.length; y++) {
    for (const [x, cell] of (grid[y] ?? []).entries()) {
      const head = cell.kind === 'arrow' ? HEADS[cell.ch] : undefined
      if (!head) continue
      const next = grid[y + head.dy]?.[x + head.dx]
      if (next && next.kind === 'border' && !next.isContinuation) {
        next.ch = head.block
        next.kind = 'arrow'
        cell.ch = head.line
        cell.kind = 'line'
      } else {
        cell.ch = head.block
      }
    }
  }
}

function toSegments(cells: Cell[]): Segment[] {
  const out: Segment[] = []
  for (const cell of cells) {
    if (cell.isContinuation) continue
    const last = out[out.length - 1]
    if (last && last.kind === cell.kind && last.href === cell.href) last.text += cell.ch
    else out.push({ text: cell.ch, kind: cell.kind, ...(cell.href ? { href: cell.href } : {}) })
  }
  // 오른쪽 끝 공백은 칠할 필요가 없다
  const last = out[out.length - 1]
  if (last && last.kind === 'text' && last.text.trim() === '') out.pop()
  return out
}

export function renderDiagram(source: string): Diagram | null {
  const cached = cache.get(source)
  if (cached !== undefined) return cached
  let diagram: Diagram | null = null
  try {
    const art = render(source)
    if (art && art.warnings.length === 0) {
      const grid = art.styled.map(toCells)
      plugArrows(grid)
      const rows = grid.map(toSegments)
      while (rows.length > 0 && (rows[rows.length - 1] ?? []).length === 0) rows.pop()
      diagram = { rows, width: art.width }
    }
  } catch {
    diagram = null
  }
  if (cache.size > 50) cache.clear()
  cache.set(source, diagram)
  return diagram
}

files.types/index.d.ts:
export type FileDiff = { path: string; added: number; removed: number; patch: string; isNew: boolean }

export type RepoInfo = { name: string; branch: string | null; isRepo: boolean }

// 터미널 배경에서 계산한 데스크톱식 회색 면. omarchy 테마를 못 읽으면 null.
export type Surface = { mode: 'light' | 'dark'; background: string; bubble: string }

export type RunCall = {
  tool_use_id: string
  tool: string
  input: unknown
  isRunning: boolean
  isErrored: boolean
  isInterrupted: boolean
  output?: unknown
}

// 답변 텍스트 없이 이어진 도구 호출 묶음. firstOf: 호출 id → 묶음 첫 호출 id.
export type Runs = { firstOf: Record<string, string>; calls: Record<string, RunCall[]> }

// 붙여 넣은 이미지 파일과 PNG 헤더의 크기. 키는 [Image #N] 의 N.
export type ImageInfo = { path: string; width: number; height: number }

// 한 턴에 편집 도구로 바꾼 파일. 턴이 끝나면 소요 시간과 함께 카드로 남는다.
export type TurnEdit = { path: string; added: number; removed: number }

// text: 그 턴의 답변(턴 끝 줄의 복사 버튼용). 예전 기록에는 없다.
// 할 일 목록 한 줄(TodoWrite·TaskCreate 에서).
export type TaskItem = { id: string; subject: string; status: 'pending' | 'in_progress' | 'completed'; activeForm?: string }

// 질문 카드: AskUserQuestion 질문 하나와 지금 묻는 상태.
export type AskQuestion = {
  question: string
  header: string
  kind: 'choice' | 'text' | 'number'
  description?: string
  options: { label: string; description?: string; preview?: string }[]
  multiSelect: boolean
  placeholder?: string
  min?: number
  max?: number
  unit?: string
}
// dir: 답 파일을 주고받는 임시 폴더. picks·texts 는 질문마다 고른 라벨과 입력한 글.
// shownAt: 지금 질문을 띄운 시각(ms). 질문이 바뀐 직후의 숫자 키는 무시한다.
export type AskState = { id: string; dir: string; questions: AskQuestion[]; step: number; picks: string[][]; texts: string[]; shownAt: number }

export type TurnCard = { durationMs: number; files: TurnEdit[]; text?: string }

// 세션 패널 한 줄: ~/.claude/projects 의 기록 파일 하나.
export type SessionEntry = { id: string; updatedAt: number; cwd: string; title: string }

// 컨텍스트 칩·패널: $.session.usage() 에서 그릴 것만 옮겨 둔 것. at 은 읽은 시각(ms).
export type UsageInfo = {
  percent: number | null
  tokens: number | null
  window: number
  limits: Array<{ kind: string; percentUsed: number; resetsAt: string | null }>
  costUsd: number | null
  at: number
}

// /context 와 같은 항목별 내역(로컬 추정). compactAt 은 자동 압축이 도는 토큰 수, 꺼져 있으면 null.
export type UsageBreakdown = {
  categories: Array<{ name: string; tokens: number; kind: string; color: string }>
  total: number
  max: number
  compactAt: number | null
  model: string
  at: number
}

// PR 바: 지금 브랜치의 GitHub PR(gh) 또는 GitLab MR(glab). checks 는 체크(GitLab 은 파이프라인 job) 하나하나,
// threads 는 안 풀린 리뷰 스레드(GitLab 은 토론). added·removed 는 모르면 null(GitLab 은 로컬 git 으로 센다).
export type PrCheck = { name: string; state: 'pass' | 'fail' | 'pending' | 'skip'; url: string | null }
export type PrThread = { path: string; line: number | null; author: string; body: string; url: string | null; isOutdated: boolean }
export type PrInfo = {
  provider: 'github' | 'gitlab'
  number: number
  title: string
  url: string
  state: 'OPEN' | 'CLOSED' | 'MERGED'
  isDraft: boolean
  reviewDecision: string | null
  mergeState: string | null
  head: string
  base: string
  added: number | null
  removed: number | null
  checks: PrCheck[]
  threads: PrThread[] | null
}
// status: none 은 PR 이 없는 브랜치, off 는 읽지 못한 경우. at 은 읽은 시각(ms).
// isSticky: off 의 원인이 로컬이라(도구가 없음, 그 호스트의 저장소가 아님) 다시 물어도 같은 경우.
// 네트워크·인증 오류는 false 라 다음 턴에 다시 읽는다.
export type PrState = { status: 'loading' | 'ok' | 'none' | 'off'; branch: string | null; pr: PrInfo | null; at: number; error?: string; isSticky?: boolean }

// diff 패널의 범위: 커밋 안 한 변경, 기본 브랜치에서 갈라진 뒤 전부, 커밋 하나씩.
export type DiffScope = 'uncommitted' | 'branch' | 'commits'
export type CommitInfo = { sha: string; short: string; subject: string; author: string; ago: string }
// base: 비교 기준(브랜치 이름과 merge-base), 못 찾으면 null. commit: 커밋별에서 펼친 커밋.
export type DiffView = { scope: DiffScope; base: { ref: string; sha: string } | null; files: FileDiff[]; commits: CommitInfo[]; commit: string | null; commitFiles: FileDiff[] }

declare module 'claude-code' {
  interface PluginState {
    'desk-look': {
      open: Record<string, boolean>
      diff: FileDiff[]
      repo: RepoInfo | null
      surface: Surface | null
      runs: Runs
      images: Record<string, ImageInfo>
      // 터미널이 kitty 그래픽을 그리는지(멀티플렉서 밖의 kitty·Ghostty).
      graphics: boolean
      pendingEdits: TurnEdit[]
      turnCards: TurnCard[]
      sessions: SessionEntry[]
      // 세션 패널 검색어.
      sessionQuery: string
      // 지금 턴이 시작된 시각(ms), 턴 밖이면 null.
      turnStartedAt: number | null
      // 스피너를 다시 그리게 하는 시계(ms).
      tick: number
      // 지금의 할 일 목록.
      tasks: TaskItem[]
      // 지금 desk-look 패널로 묻고 있는 질문, 없으면 null.
      ask: AskState | null
      // 컨텍스트·사용 한도(턴이 끝날 때마다), 그리고 컨텍스트 패널을 열 때 계산한 항목별 내역.
      usage: UsageInfo | null
      usageBreakdown: UsageBreakdown | null
      // Button 안에 글·Text 를 넣을 수 있는 엔진(2.1.295+)인지.
      richButtons: boolean
      // 지금 브랜치의 PR(PR 바·/desk-pr 패널).
      pr: PrState | null
      // /desk-diff 패널이 보여 주는 범위와 그 diff.
      diffView: DiffView
    }
  }
}
